MagickBooleanType TraceBezier(void)
{
  Coefficient *coefficients = (Coefficient *) AcquireQuantumMemory(4, sizeof(*coefficients));
  Point *points = (Point *) AcquireQuantumMemory(4, sizeof(*points));
  double control_point[4][2];
  double t;
  size_t i, j;

  if ((coefficients == (Coefficient *) NULL) || (points == (Point *) NULL))
  {
    InserQuantumMemoryException;
    return MagickFalse;
  }

  for (i = 0; i < 4; i++)
  {
    control_point[i][0] = cos(i * (M_PI / 3));
    control_point[i][1] = sin(i * (M_PI / 3));
  }

  for (t = 0.0; t <= 1.0; t += 0.1)
  {
    double x = 0.0, y = 0.0;

    for (i = 0; i < 4; i++)
    {
      coefficients[i] = BinomialCoefficient(3, i) * pow(1.0 - t, 3 - i) * pow(t, i);
      x += coefficients[i] * control_point[i][0];
      y += coefficients[i] * control_point[i][1];
    }

    points[i].x = x;
    points[i].y = y;
  }

  if (!CheckPrimitiveExtent(points))
  {
    RelinquishMemory(points);
    RelinquishMemory(coefficients);
    ThrowMagickException(...);
    return MagickFalse;
  }

  return MagickTrue;
}

